const escape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(v)+' ₸';
export function readiness(result,source,today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Almaty',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())){
  return {age:Math.max(0,Math.floor((Date.parse(today+'T00:00:00Z')-Date.parse(result.end+'T00:00:00Z'))/86400000)),forecast:result.products.filter(p=>p.days>=7).length,comparison:result.products.filter(p=>p.days>=42).length,test:result.products.filter(p=>p.days>=70).length,total:result.products.length,demo:source==='demo'};
}
export function briefing(result,source){
  const ready=readiness(result,source);
  return [`Qadam AI · сводка магазина`,source==='demo'?'ДЕМОНСТРАЦИЯ · вымышленные данные':'Источник: загруженный CSV',`Период продаж: ${result.start} — ${result.end}`,`Остатки на: ${result.end}`,`Выручка: ${money(result.revenue)}`,`Валовая прибыль: ${money(result.margin)} (до расходов, налогов и комиссий)`,`Товары с достаточной историей для прогноза: ${ready.forecast}/${ready.total}`,`Рекомендуемый бюджет закупки: ${money(result.budget)} (оценка по себестоимости)`, '', 'План пополнения:',...result.actions.map(p=>`${p.sku} · ${p.name}: ${p.suggested} шт., ≈ ${money(p.budget)}`),'','Это рекомендации, не подтверждённые заказы. Прогноз не гарантирует продажи; цены и наличие согласуются с поставщиком.','Проверенные продажи, заказы и счета сохраняются на сервере.'].join('\n');
}
const steps=[['overview','Продажи','Покажите выручку и валовую прибыль. Уточните, что демоданные вымышленные.'],['forecast','Прогноз','Выберите товар и раскройте сравнение методов. Меньшая ошибка на прошлых данных не гарантирует будущий результат.'],['actions','Пополнение','Объясните количество: прогноз на срок поставки плюс буфер, минус остаток и товар в пути.'],['suppliers','Заказ','Покажите форму заказа и счета. Учебные заказы отправить нельзя; реальный заказ требует подтверждения.'],['presentation','Итоги','Объясните, что уже работает и что нужно проверить на данных реального магазина.']];
let touring=false;
export function presentationPage(){return `<div class="page-head"><div><h1>Показать Qadam</h1><p class="subtitle">От продаж до согласованной закупки — за пять шагов.</p></div><button class="button primary" id="start-tour">Начать показ</button></div><section class="pitch-hero"><span class="eyebrow">ПОМОЩНИК ВЛАДЕЛЬЦА МАГАЗИНА</span><h2>Что заказать.<br>Когда пополнить.<br>Как не забыть оплатить.</h2><p>Qadam связывает историю продаж, прогноз спроса и работу с поставщиком в одном рабочем пространстве.</p><a href="#suppliers" class="button">Открыть закупки →</a></section><div class="pitch-grid"><section class="panel"><h2>Уже можно показать</h2><ul class="feature-list"><li>Импорт CSV с проверкой ошибок</li><li>Прогноз и сравнение методов на истории</li><li>План закупок с объяснением расчёта</li><li>Telegram-заказы после подтверждения</li><li>Счета, статусы и уведомления об оплате</li></ul></section><section class="panel"><h2>Следующий этап — пилот</h2><p class="note">Нужны продажи и остатки реального магазина. Проверяем точность прогноза, удобство закупки и время на обработку заказа.</p><p class="note">Экономия и рост прибыли пока не измерены. Интеграции маркетплейсов, автоматическая оплата и автоматическое изменение склада не реализованы.</p></section></div><section class="panel"><h2>Как это работает</h2><ol class="flow-list"><li><strong>CSV</strong><span>Продажи проверяются и сохраняются с историей загрузок.</span></li><li><strong>Прогноз</strong><span>Пять базовых методов; CatBoost, LightGBM и Isolation Forest подключаются через отчёт, рассчитанный в Python.</span></li><li><strong>Решение</strong><span>Количество закупки рассчитывается по выбранному прогнозу.</span></li><li><strong>Telegram + база</strong><span>Заказы сохраняются на сервере, отправка — после подтверждения. Поставщик присылает счёт ответом на заказ.</span></li></ol></section>`;}
export function decoratePresentation(app,view,result,state){
  const ready=readiness(result,state.source);
  if(view==='overview'){
    app.querySelector('.page-head').insertAdjacentHTML('afterend',`<section class="decision-strip"><div><span class="eyebrow">СЛЕДУЮЩЕЕ ДЕЙСТВИЕ</span><strong>${result.actions.length?'Позиций для пополнения: '+result.actions.length:'Посмотрите прогноз спроса'}</strong><span>${result.actions.length?'Расчётный бюджет '+money(result.budget):'План закупок не требует пополнения по текущим данным.'}</span></div><a class="button primary" href="#${result.actions.length?'actions':'forecast'}">${result.actions.length?'Перейти к плану':'Открыть прогноз'} →</a></section>`);
    app.insertAdjacentHTML('beforeend',`<section class="panel readiness-panel"><div class="panel-head"><h2>Готовность данных</h2><button class="button" id="download-brief">Скачать сводку</button></div><div class="readiness-grid"><div><span>Последние данные</span><strong>${escape(result.end)}</strong><small>${ready.demo?'Учебный набор':ready.age>7?'Данные старше недели — обновите остатки':ready.age+' дн. назад'}</small></div><div><span>Готовы к прогнозу</span><strong>${ready.forecast} / ${ready.total}</strong><small>Предварительно от 7 дней</small></div><div><span>Доступен отдельный тест</span><strong>${ready.test} / ${ready.total}</strong><small>От 70 дней на товар</small></div></div><details><summary>Как читать эти показатели</summary><p class="note">Для сравнения базовых методов достаточно истории у ${ready.comparison} из ${ready.total} товаров (от 42 дней). Длина истории не подтверждает точность прогноза. Проверка CSV выявляет ошибки формата, но не доказывает достоверность продаж. Запасы и рекомендации относятся к дате последней строки.</p></details></section>`);
    app.querySelector('#download-brief').onclick=()=>{const u=URL.createObjectURL(new Blob(['\uFEFF',briefing(result,state.source)],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='qadam-summary-'+result.end+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
  }
  app.querySelector('#start-tour')?.addEventListener('click',()=>{touring=true;location.hash='overview';});
  document.querySelector('#guided-tour')?.remove();
  if(touring){const index=steps.findIndex(s=>s[0]===view);if(index<0)return;const bar=document.createElement('section');bar.id='guided-tour';bar.className='tour-bar';bar.setAttribute('aria-label','Сценарий презентации');bar.innerHTML=`<div><span class="eyebrow">ПОКАЗ · ${index+1} / ${steps.length}</span><strong>${steps[index][1]}</strong><p>${steps[index][2]}</p></div><div class="tour-controls">${index?`<a class="button" href="#${steps[index-1][0]}">Назад</a>`:''}${index<steps.length-1?`<a class="button primary" href="#${steps[index+1][0]}">Далее →</a>`:''}<button class="button" id="end-tour">Завершить</button></div>`;app.before(bar);bar.querySelector('#end-tour').onclick=()=>{touring=false;bar.remove();};}
}
